import {Banner} from '@primer/react'
import {useState} from 'react'

type Status = {type: 'idle'} | {type: 'loading'} | {type: 'success'} | {type: 'error'; errorCode: string}

export interface BrowserGeoLocationProps {
  locationSharedInputId: string
  latitudeInputId: string
  longitudeInputId: string
}

export function BrowserGeoLocation({
  locationSharedInputId,
  latitudeInputId,
  longitudeInputId,
}: BrowserGeoLocationProps) {
  const [status, setStatus] = useState<Status>({type: 'idle'})

  const handleShareLocationClick = async (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault()
    if (status.type === 'loading') return
    setStatus({type: 'loading'})
    const locationSharedInput = document.getElementById(locationSharedInputId) as HTMLInputElement

    try {
      if (navigator.geolocation) {
        const position = await new Promise<GeolocationPosition>((resolve, reject) => {
          navigator.geolocation.getCurrentPosition(resolve, reject)
        })

        const latitude = position.coords.latitude
        const longitude = position.coords.longitude

        const latitudeField = document.getElementById(latitudeInputId) as HTMLInputElement
        const longitudeField = document.getElementById(longitudeInputId) as HTMLInputElement

        if (latitudeField) latitudeField.value = latitude.toString()
        if (longitudeField) longitudeField.value = longitude.toString()

        if (locationSharedInput) locationSharedInput.value = 'true'
        setStatus({type: 'success'})
      } else {
        if (locationSharedInput) locationSharedInput.value = 'false'
        setStatus({type: 'error', errorCode: 'GEOLOCATION_UNSUPPORTED'})
      }
    } catch (e) {
      if (locationSharedInput) locationSharedInput.value = 'false'
      let errorCode = 'GEOLOCATION_UNKNOWN_ERROR'
      if (e instanceof GeolocationPositionError) {
        if (e.code === e.PERMISSION_DENIED) {
          errorCode = 'GEOLOCATION_DENIED'
        } else if (e.code === e.POSITION_UNAVAILABLE) {
          errorCode = 'GEOLOCATION_POSITION_UNAVAILABLE'
        } else if (e.code === e.TIMEOUT) {
          errorCode = 'GEOLOCATION_TIMEOUT'
        }
      }
      setStatus({type: 'error', errorCode})
    }
  }

  const getButtonText = () => {
    switch (status.type) {
      case 'loading':
        return 'Getting location...'
      case 'success':
        return '✓ Location shared'
      case 'error':
        return 'Error getting location'
      default:
        return 'Share Location'
    }
  }

  const getErrorDetail = () => {
    if (status.type !== 'error') return null

    switch (status.errorCode) {
      case 'GEOLOCATION_UNSUPPORTED':
        return 'Your browser does not support geolocation.'
      case 'GEOLOCATION_DENIED':
        return 'Permission to access location was denied by a security policy.'
      case 'GEOLOCATION_POSITION_UNAVAILABLE':
        return 'Location information is unavailable.'
      case 'GEOLOCATION_TIMEOUT':
        return 'The request to get your location timed out.'
      default:
        return 'An unknown error occurred within your browser while trying to get your location.'
    }
  }

  const getButtonClasses = () => {
    const baseClasses = 'btn float-left mt-2'

    switch (status.type) {
      case 'success':
        return `${baseClasses} btn-success`
      case 'error':
        return `${baseClasses} btn-danger`
      default:
        return `${baseClasses} btn-primary`
    }
  }

  return (
    <>
      {status.type === 'error' && (
        <Banner variant="critical" className="my-2">
          <Banner.Title>Unable to access location</Banner.Title>
          <Banner.Description>
            <p>{getErrorDetail()}</p>
            <p>
              Make sure location access is allowed in your browser/OS and platform settings. Disable VPN and add-ons,
              clear cookies/cache, and try a different browser (preferably Chrome). Log out and back in after adjusting
              settings, then re-apply. If issues persist, try applying from your smartphone using mobile data instead of
              WiFi.
            </p>
          </Banner.Description>
        </Banner>
      )}
      <button
        type="button"
        className={getButtonClasses()}
        onClick={handleShareLocationClick}
        disabled={status.type === 'loading' || status.type === 'success'}
        aria-busy={status.type === 'loading'}
      >
        {getButtonText()}
      </button>
    </>
  )
}
